/**
 * Throws if `value` is not an array.
 * @param {unknown} value Value to test.
 * @param {string} label Label for error message context.
 * @returns {void}
 */
function assertIntervalList(value) {
  if (!Array.isArray(value)) {
    throw new TypeError('interval list must be an array');
  }
  for (const member of value) {
    if (!Array.isArray(member) || member.length !== 2) {
      throw new TypeError('interval must be a two-element array');
    }
    const [start, end] = member;
    if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end)) {
      throw new TypeError('interval bounds must be safe integers');
    }
    if (start > end) {
      throw new RangeError('interval start must not exceed end');
    }
  }
}

/**
 * Normalises a list of intervals: drops empties, sorts, and coalesces
 * overlapping or touching intervals.
 * @param {unknown} intervals Interval list.
 * @returns {Array<[number, number]>} Normalised list.
 */
export function normalize(intervals) {
  assertIntervalList(intervals);
  const kept = [];
  for (const iv of intervals) {
    const [start, end] = iv;
    if (end > start) {
      // Freshly allocate each interval.
      kept.push([start, end]);
    }
  }
  kept.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  const out = [];
  for (const iv of kept) {
    if (out.length === 0) {
      out.push([iv[0], iv[1]]);
    } else {
      const last = out[out.length - 1];
      if (iv[0] <= last[1]) {
        // Overlapping or touching: coalesce. Touching means iv[0] === last[1],
        // which extends the covered range since [a, b) ∪ [b, c) = [a, c).
        if (iv[1] > last[1]) {
          last[1] = iv[1];
        }
      } else {
        out.push([iv[0], iv[1]]);
      }
    }
  }
  return out;
}

/**
 * Union of two interval lists.
 * @param {unknown} a First interval list.
 * @param {unknown} b Second interval list.
 * @returns {Array<[number, number]>} Normalised union.
 */
export function merge(a, b) {
  assertIntervalList(a);
  assertIntervalList(b);
  return normalize([...a, ...b]);
}

/**
 * Intersection of two interval lists. Touching intervals do not intersect.
 * @param {unknown} a First interval list.
 * @param {unknown} b Second interval list.
 * @returns {Array<[number, number]>} Normalised intersection.
 */
export function intersect(a, b) {
  assertIntervalList(a);
  assertIntervalList(b);
  const na = normalize(a);
  const nb = normalize(b);

  const out = [];
  let i = 0;
  let j = 0;
  while (i < na.length && j < nb.length) {
    const [as, ae] = na[i];
    const [bs, be] = nb[j];
    const start = as > bs ? as : bs;
    const end = ae < be ? ae : be;
    if (end > start) {
      // end > start guarantees a non-empty, genuinely overlapping interval;
      // touching (end === start) yields nothing.
      out.push([start, end]);
    }
    if (ae < be) {
      i += 1;
    } else if (be < ae) {
      j += 1;
    } else {
      i += 1;
      j += 1;
    }
  }
  return out;
}

/**
 * Relative complement `a \ b`.
 * @param {unknown} a Interval list to subtract from.
 * @param {unknown} b Interval list to remove.
 * @returns {Array<[number, number]>} Normalised difference.
 */
export function subtract(a, b) {
  assertIntervalList(a);
  assertIntervalList(b);
  const na = normalize(a);
  const nb = normalize(b);

  const out = [];
  let j = 0;
  for (const [as, ae] of na) {
    let curStart = as;
    // Advance through b intervals that end before or at the current segment's start.
    while (j < nb.length && nb[j][1] <= curStart) {
      j += 1;
    }
    let k = j;
    while (k < nb.length && nb[k][0] < ae) {
      const [bs, be] = nb[k];
      if (bs > curStart) {
        out.push([curStart, bs]);
      }
      if (be < ae) {
        curStart = be;
      } else {
        curStart = ae;
        break;
      }
      k += 1;
    }
    if (curStart < ae) {
      out.push([curStart, ae]);
    }
  }
  return out;
}

/**
 * Total length covered by a list of intervals, counting overlaps once.
 * @param {unknown} intervals Interval list.
 * @returns {number} Number of integers covered.
 */
export function coverage(intervals) {
  assertIntervalList(intervals);
  const norm = normalize(intervals);
  let total = 0;
  for (const [start, end] of norm) {
    total += end - start;
  }
  return total;
}
